tool_calls:
Execute: $ cat > /tmp/stack.mjs <<'EOF'
import { chromium } from '/usr/local/lib/node_modules/playwright/index.mjs';
const b = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swangle-shader'] });
const p = await b.newPage();
p.on('pageerror', e => console.log('PAGEERROR:', e.stack || String(e)));
p.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
await p.goto('http://127.0.0.1:8124/index.html', { waitUntil: 'domcontentloaded' });
await new Promise(r => setTimeout(r, 4000));
await b.close();
EOF
node /tmp/stack.mjs

Execute: $ cat > /tmp/shots.mjs <<'EOF'
import { chromium } from '/usr/local/lib/node_modules/playwright/index.mjs';
const b = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swangle-shader','--window-size=1600,1000','--disable-background-timer-throttling'] });
const p = await b.newPage({ viewport: { width: 1600, height: 1000 } });
await p.goto('http://127.0.0.1:8124/index.html', { waitUntil: 'domcontentloaded' });
await new Promise(r => setTimeout(r, 2500));
await p.click('.starter-card:nth-child(1) .sc-btn');
await new Promise(r => setTimeout(r, 800));
// sealed gate + warden from the player's approach
await p.evaluate(() => { const g = window.__game; g._debugTeleport(4, -62); g.player.camYaw = Math.PI; });
await new Promise(r => setTimeout(r, 2200));
await p.screenshot({ path: '/company/repos/cosmon-game/screenshot-gate-sealed.webp' });
// trainer NPC in the world
await p.evaluate(() => { const g = window.__game; g._debugTeleport(-27, -10); });
await new Promise(r => setTimeout(r, 2200));
await p.screenshot({ path: '/company/repos/cosmon-game/screenshot-trainer-world.webp' });
await b.close();
EOF
node /tmp/shots.mjs && echo SHOTS-OK

